import json,runpy,copy
from pathlib import Path
S=Path(__file__).resolve().parents[1];d=json.loads((S/'data/catalog.json').read_text(encoding='utf8'));n=runpy.run_path(str(S/'work/write_bds_early.py'))['base']
p=S/'analysis/SuperBDS.json';res=json.loads(p.read_text(encoding='utf8'))
a=copy.deepcopy(res['SuperBDS/StgBDS']);a['summary']='價格跨越等距格線時建立BPS基準，之後突破該線上下距離做多／空一口；每條線只交易一次，退出後停止。';a['entry']=['由BD線基點及間隔生成整數格線，比較前後兩筆open所跨過的每條線，逐條嘗試新增；與啟動基準距離小於半個間隔時不重建。','上下目標=格線±多空進場距離；達上側買多、達下側放空，實際以當筆open成交並把該方向目標設成成交價。新建線同根就可入場。'];a['mechanics']=['先依價格跨線新增基準，再執行全部啟動線；沒有每日首筆畫線或同根只進一條的限制，一次跳空可建多條及同時開倉。','單條先按KBAR相位篩選並把OHLC覆為open，一口進出；結算在一般交易判斷後，依價差平移並平舊開新。'];a['exit']=['尚無移停線只檢查固定停損；已有線才先檢查直停再檢查回撤，最後更新移停。退出後已進一次就停止，不容許這條線再次進場。','回測尾端只停止剩餘線，沒有為在倉部位另建最後平倉。'];a['caveats']=['需正的格線間隔，0會除以0；空資料直接讀ds[0]會出錯。第一筆只作比較起點，不建基準。','同位置舊線停止後，日後再跨格線可重新建另一條，並非整段回測每個價位只交易一次。','直停仍需先有移停線才檢查；同根能建立多條策略，沒有總口數／現金上限或尾端強平。'];nn=dict(n);nn.update({'多空進場比':'格線上／下的共用突破距離；%按格線價換算，沒有最少進場點下限。','BD線基點':'整個價格格線的原點，格線為基點+k×間隔。','BD線間隔':'價格格線點數間隔，必須>0；新線與啟動基準距離小於其一半時不建。'});i=next(i for i in d['items'] if i['id']=='SuperBDS/StgBPS');a['parameterNotes']={p['name']:nn[p['name']] for p in i['parameters']};res[i['id']]=a
for name in ['StgBHS','StgBHSv2']:
 v=name.endswith('v2');nn=dict(n);nn.update({'KBAR間隔ex':'此核心逐筆open處理，沒有呼叫ValidKBAR，參數不改交易頻率。','開始交易時間':'本核心沒有用此欄限制進場或建立KBAR相位。','進場模式':'每年第n個曆日後首個有資料日，或每年第n月結算後首個有資料日建立年度策略。','第n日或月':'日模式由1月1日加n−1個曆日，非第n交易日；月模式選結算後首日所在月份。','到期動作':'出場並停止時，在下一次年度排程或資料結尾的前一筆open退出；繼續時不執行這個年度到期平倉。','加碼間隔':'目標多／空每次前移或後退的點數間距。'+('v2在建線時可按基準價百分比換算並按tick取整，之後固定該步距。' if v else '此版直接固定點數。'),'加碼方式':'向上加碼每次保持一口；其餘模式進一階後下一批口數減一、退一階後加一；只有向下加碼在空手再下移目標時也增加下一批口數。','停損':'每個階梯目標下方的退階距離，觸發減碼／平倉並下調目標，不一定永久停止。'+('v2建線時可按基準價百分比換算。' if v else ''),'直接停利':'策略總點數損益的停利預算；用目前部位轉成價格目標，或按上漲區間模擬加碼量。'+('v2的%按計算當時價格換算點數預算，非將淨值乘收益率。' if v else ''),'最大損失':'策略總點數損失預算，用目前部位及已累積損益換成停止價；不是每口固定損失。'+('v2允許%按當時價格換成預算。' if v else ''),'停利計算方式':'淨獲利會把先前累積現金流也計入尚需獲利；只計算上漲獲利則按上漲跨階梯的預期部位計算價格目標。','啟動移停':'以策略當前總點數獲利達此門檻啟動追蹤，%用當筆價格換成點數。','移停拉回':'最大總獲利相對目前總獲利的回撤門檻，%按當筆價格換算，不是從商品價高點的百分比。'})
 a={'summary':'依年度日期建立只做多的階梯策略；價格上穿目標時買入、跌破階梯停損時賣出退階，空手續跌可重畫較低目標，待反彈再進。'+('v2加上百分比距離與策略總獲利移停。' if v else ''),'family':'網格與分批','entry':['年排程日首筆open建基準，初始目標多等於open，通常同根即買第一口。之後price達目標多才以計畫口數再買，目標多上移一個加碼間隔。','向上加碼固定每階一口；其他方式進階後下一批口數減一，退階則加一。空手跌到目標空時只下調基準／停損，向下加碼才再增加下一批買入量。'],'exit':['先檢查總停利價格，再檢查'+('總獲利移停，然後最大損失價格；' if v else '最大損失價格；')+'達到便全部退出停止。一般跌到階梯停損價則賣出該批口數、下調目標，策略可繼續。','到期動作選停止時，在下一個年度日期之前一筆open平倉並停；選繼續時可跨年度重疊，資料最後只標停止，沒有另外尾端強平。'],'mechanics':['全部判斷及成交用open，並將OHLC覆成open；沒有KBAR過濾或日內高低觸價。部位由階梯規則變動，未呼叫共用資金轉口數。','停利與最大損失預算以累積損益及目前部位換成價格；同一檔可有多個年度策略共存。結算交易只平開一口，即使現有部位較多，也會平移整條策略的價格。'],'caveats':['策略雖名BuyHold，實際包含減碼、重新畫線及反彈重入；向下加碼並非每跌一格立即買入。','年度停用迴圈正向走訪且移除目前元素，多個年度策略重疊時可能跳過下一個；不能把到期當成保證一次全數出清。','資料尾端僅在到期停止模式對當時處理到的策略平倉；繼續模式只標停止，未平部位仍可能存在。','加碼間隔需正值，停利價格推算的迴圈及除法沒有完整輸入保護。結算只平開一口與實際多口部位不一致，成本呈現需注意。'],'parameterNotes':{pp['name']:nn[pp['name']] for pp in next(i for i in d['items'] if i['id']=='SuperBDS/'+name)['parameters']}}
 if v:
  a['exit'].insert(0,'最大獲利追蹤用已實現加未實現現金流及部位×open的總點數；啟動後若自最大值回撤達門檻就全出停止，並不比較價格高點。')
  a['caveats'].append('百分比會換成價格點數預算，非投資本金報酬率；移停門檻在每筆按目前價格換算，會隨價格變動。')
 res['SuperBDS/'+name]=a
p.write_text(json.dumps(res,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote BPS and BHS2')
